define(["jquery"],function($){"use strict";const init=function(){const banner=document.querySelector("[data-pdfprotect-superflipbook-banner]");if(!banner){return}const button=banner.querySelector("[data-pdfprotect-superflipbook-dismiss]");const error=banner.querySelector("[data-pdfprotect-superflipbook-error]");if(!button){return}button.addEventListener("click",function(){if(button.disabled){return}button.disabled=true;if(error){error.hidden=true}const body=new URLSearchParams;body.set("sesskey",M.cfg.sesskey);fetch(banner.getAttribute("data-dismiss-url"),{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/x-www-form-urlencoded; charset=UTF-8"},body:body.toString()}).then(function(response){if(!response.ok){throw new Error("Could not dismiss the Super Flipbook banner.")}return response.json()}).then(function(result){if(!result.success){throw new Error("Super Flipbook banner dismissal was not saved.")}banner.remove()}).catch(function(){button.disabled=false;if(error){error.hidden=false}})})};return{init:init}});